}
EOF
cat > UITests/NavigationTests.swift <<'EOF'
import XCTest

final class NavigationTests: XCTestCase {
    func testOpenAppearance() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        if springboard.alerts.buttons["Open"].waitForExistence(timeout: 3) {
            springboard.alerts.buttons["Open"].tap()
        }
        sleep(3)
        print("BLUESKY TREE BEFORE MENU: \(app.debugDescription)")
        let window = app.windows.firstMatch
        let hamburger = window.coordinate(withNormalizedOffset: CGVector(dx: 0.075, dy: 0.095))
        hamburger.tap()
        sleep(2)
        print("BLUESKY TREE AFTER MENU: \(app.debugDescription)")
        if app.buttons["Settings"].exists {
            app.buttons["Settings"].tap()
        } else if app.staticTexts["Settings"].exists {
            app.staticTexts["Settings"].tap()
        } else {
            window.coordinate(withNormalizedOffset: CGVector(dx: 0.18, dy: 0.36)).tap()
        }
        sleep(2)
        print("BLUESKY TREE AFTER SETTINGS: \(app.debugDescription)")
        if app.buttons["Appearance"].exists {
            app.buttons["Appearance"].tap()
        } else if app.staticTexts["Appearance"].exists {
            app.staticTexts["Appearance"].tap()
        } else {
            window.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.45)).tap()
        }
        sleep(2)
        print("BLUESKY TREE AT END: \(app.debugDescription)")
    }
}
EOF
